import React, { useState, useEffect, useRef, useCallback } from 'react';
import api from '../../utils/api';
import { Building, Check, Globe, MapPin, Search, Target } from '../shared/Icons.js';

// ── Inline LocationPicker (self-contained, no external import needed) ─────────
const REGION_FLAGS = { Africa:Globe, Europe:Globe, 'North America':Globe, 'South America':Globe, 'Middle East':Globe, Asia:Globe, Oceania:Globe };
const TYPE_ICON    = { country:Globe, city:Building, region:MapPin };

function LocationTag({ loc, onRemove }) {
  return (
    <div style={{ display:'inline-flex', alignItems:'center', gap:5, padding:'4px 10px', borderRadius:20, background:'rgba(124,58,237,0.12)', border:'1px solid rgba(124,58,237,0.3)', fontSize:12, fontWeight:600, color:'var(--purple-light)', maxWidth:'100%' }}>
      <span>{TYPE_ICON[loc.type] || MapPin}</span>
      <span style={{ overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{loc.label}</span>
      <button onClick={() => onRemove(loc.id)} style={{ background:'none', border:'none', color:'var(--purple-light)', cursor:'pointer', padding:'0 2px', fontSize:14, lineHeight:1, opacity:0.7 }}>×</button>
    </div>
  );
}

function LocationPicker({ value = [], onChange, maxLocations = 10 }) {
  const [query,       setQuery]       = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [searching,   setSearching]   = useState(false);
  const [open,        setOpen]        = useState(false);
  const [activeIdx,   setActiveIdx]   = useState(-1);
  const inputRef   = useRef();
  const dropRef    = useRef();
  const debounceRef = useRef();

  useEffect(() => {
    const handler = (e) => { if (dropRef.current && !dropRef.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  useEffect(() => {
    clearTimeout(debounceRef.current);
    if (query.length < 2) { setSuggestions([]); setOpen(false); return; }
    setSearching(true);
    debounceRef.current = setTimeout(async () => {
      try {
        const res = await api.get(`/locations/search?q=${encodeURIComponent(query)}`);
        const selectedIds = new Set(value.map(v => v.id));
        setSuggestions(res.data.filter(s => !selectedIds.has(s.id)));
        setOpen(true); setActiveIdx(-1);
      } catch { setSuggestions([]); }
      finally { setSearching(false); }
    }, 280);
  }, [query, value]);

  const selectLocation = useCallback((loc) => {
    if (value.length >= maxLocations) return;
    onChange([...value, loc]);
    setQuery(''); setSuggestions([]); setOpen(false);
    inputRef.current?.focus();
  }, [value, onChange, maxLocations]);

  const removeLocation = useCallback((id) => {
    onChange(value.filter(v => v.id !== id));
  }, [value, onChange]);

  const handleKeyDown = (e) => {
    if (!open || !suggestions.length) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIdx(i => Math.min(i+1, suggestions.length-1)); }
    if (e.key === 'ArrowUp')   { e.preventDefault(); setActiveIdx(i => Math.max(i-1, -1)); }
    if (e.key === 'Enter' && activeIdx >= 0) { e.preventDefault(); selectLocation(suggestions[activeIdx]); }
    if (e.key === 'Escape') { setOpen(false); setQuery(''); }
    if (e.key === 'Backspace' && query === '' && value.length > 0) removeLocation(value[value.length-1].id);
  };

  const grouped = suggestions.reduce((acc, s) => {
    const k = s.region || 'Other';
    if (!acc[k]) acc[k] = [];
    acc[k].push(s);
    return acc;
  }, {});

  return (
    <div ref={dropRef} style={{ position:'relative', width:'100%' }}>
      {/* Input + tags area */}
      <div onClick={() => inputRef.current?.focus()} style={{ minHeight:42, padding:'6px 10px', background:'var(--bg-elevated)', border:'1px solid var(--border-subtle)', borderRadius:10, display:'flex', flexWrap:'wrap', gap:6, alignItems:'center', cursor:'text', ...(open?{borderColor:'var(--purple-primary)',boxShadow:'0 0 0 2px rgba(124,58,237,0.15)'}:{}) }}>
        {value.map(loc => <LocationTag key={loc.id} loc={loc} onRemove={removeLocation} />)}
        {value.length < maxLocations && (
          <input ref={inputRef} value={query} onChange={e => setQuery(e.target.value)} onKeyDown={handleKeyDown} onFocus={() => query.length >= 2 && setOpen(true)}
            placeholder={value.length === 0 ? 'Search country or city...' : 'Add more...'}
            style={{ flex:'1 1 140px', minWidth:120, background:'transparent', border:'none', outline:'none', fontSize:13, color:'var(--text-primary)', fontFamily:'DM Sans,sans-serif', padding:'2px 0' }}
          />
        )}
        {searching && <span style={{ fontSize:11, color:'var(--text-faint)', marginLeft:'auto' }}>searching...</span>}
      </div>

      {/* Helper */}
      <div style={{ fontSize:11, color:'var(--text-faint)', marginTop:4, display:'flex', justifyContent:'space-between' }}>
        <span>Works on all platforms — each location is mapped to the correct platform ID automatically</span>
        <span style={{ color: value.length >= maxLocations ? '#ef4444' : 'var(--text-faint)' }}>{value.length}/{maxLocations}</span>
      </div>

      {/* Platform mapping confirmation */}
      {value.length > 0 && (
        <div style={{ marginTop:10, padding:'10px 14px', borderRadius:10, background:'rgba(124,58,237,0.05)', border:'1px solid rgba(124,58,237,0.15)' }}>
          <div style={{ fontSize:11, fontWeight:700, color:'var(--purple-light)', marginBottom:8, textTransform:'uppercase', letterSpacing:'0.05em' }}><Check size={14}/> Platform targeting mapped</div>
          <div style={{ display:'flex', flexWrap:'wrap', gap:6 }}>
            {[
              { key:'meta',     label:'Meta',      color:'#1877f2' },
              { key:'google',   label:'Google',    color:'#4285f4' },
              { key:'tiktok',   label:'TikTok',    color:'#010101' },
              { key:'linkedin', label:'LinkedIn',  color:'#0a66c2' },
              { key:'twitter',  label:'X/Twitter', color:'#000000' },
              { key:'snapchat', label:'Snapchat',  color:'#fffc00' },
            ].map(p => {
              const firstLoc = value[0];
              const hasId = firstLoc?.platforms?.[p.key] !== undefined;
              return (
                <div key={p.key} style={{ padding:'3px 10px', borderRadius:6, fontSize:11, fontWeight:600, background:`${hasId ? p.color : '#888'}18`, color:hasId ? p.color : 'var(--text-faint)', border:`1px solid ${hasId ? p.color+'40' : 'var(--border-subtle)'}` }}>
                  {hasId ? `${p.label}` : `— ${p.label}`}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Dropdown */}
      {open && suggestions.length > 0 && (
        <div style={{ position:'absolute', top:'100%', left:0, right:0, zIndex:999, marginTop:4, background:'var(--bg-card)', border:'1px solid var(--border-subtle)', borderRadius:12, boxShadow:'0 8px 32px rgba(0,0,0,0.2)', overflow:'hidden', maxHeight:300, overflowY:'auto' }}>
          {Object.entries(grouped).map(([region, locs]) => (
            <div key={region}>
              <div style={{ padding:'6px 14px', fontSize:10, fontWeight:700, color:'var(--text-faint)', textTransform:'uppercase', letterSpacing:'0.08em', background:'var(--bg-elevated)', borderBottom:'1px solid var(--border-subtle)' }}>
                {REGION_FLAGS[region] || Globe} {region}
              </div>
              {locs.map(loc => {
                const flatIdx = suggestions.indexOf(loc);
                const isActive = flatIdx === activeIdx;
                return (
                  <div key={loc.id} onMouseEnter={() => setActiveIdx(flatIdx)} onMouseDown={e => { e.preventDefault(); selectLocation(loc); }}
                    style={{ padding:'9px 14px', cursor:'pointer', display:'flex', alignItems:'center', gap:10, background:isActive?'rgba(124,58,237,0.1)':'transparent', borderBottom:'1px solid var(--border-subtle)', transition:'background 0.1s' }}>
                    <span style={{ fontSize:16, flexShrink:0 }}>{TYPE_ICON[loc.type] || MapPin}</span>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontSize:13, fontWeight:600, color:'var(--text-primary)' }}>{loc.label}</div>
                      <div style={{ fontSize:11, color:'var(--text-faint)', marginTop:1 }}>
                        {loc.type === 'country' ? 'Country' : `City · ${loc.country}`} · <span style={{ color:'var(--purple-light)' }}>All platforms mapped <Check size={14}/></span>
                      </div>
                    </div>
                    {isActive && <span style={{ fontSize:11, color:'var(--purple-light)', fontWeight:700 }}>↵</span>}
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      )}

      {/* No results */}
      {open && query.length >= 2 && !searching && suggestions.length === 0 && (
        <div style={{ position:'absolute', top:'100%', left:0, right:0, zIndex:999, marginTop:4, background:'var(--bg-card)', border:'1px solid var(--border-subtle)', borderRadius:12, padding:16, textAlign:'center' }}>
          <div style={{ fontSize:20, marginBottom:6 }}><Search size={14}/></div>
          <div style={{ fontSize:13, color:'var(--text-muted)', fontWeight:600 }}>No results for "{query}"</div>
          <div style={{ fontSize:11, color:'var(--text-faint)', marginTop:4 }}>Try a country name or major city</div>
        </div>
      )}
    </div>
  );
}

// ── Interest tag pill input ────────────────────────────────────────────────────
const INTEREST_SUGGESTIONS = [
  'Technology', 'Fashion', 'Sports', 'Travel', 'Food & Dining', 'Health & Fitness',
  'Business', 'Entertainment', 'Gaming', 'Automotive', 'Real Estate', 'Education',
  'Finance & Banking', 'Music', 'Beauty', 'Parenting', 'Photography', 'Politics',
  'Shopping', 'Home & Garden'
];

function InterestPicker({ value = [], onChange }) {
  const [input, setInput] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  const filtered = INTEREST_SUGGESTIONS.filter(s =>
    s.toLowerCase().includes(input.toLowerCase()) && !value.includes(s)
  );

  const addInterest = (interest) => {
    const trimmed = interest.trim();
    if (trimmed && !value.includes(trimmed)) {
      onChange([...value, trimmed]);
    }
    setInput('');
    setShowSuggestions(false);
  };

  const removeInterest = (interest) => onChange(value.filter(v => v !== interest));

  return (
    <div style={{ position:'relative' }}>
      <div style={{ display:'flex', flexWrap:'wrap', gap:6, marginBottom:8 }}>
        {value.map(interest => (
          <div key={interest} style={{ display:'inline-flex', alignItems:'center', gap:5, padding:'4px 10px', borderRadius:20, background:'rgba(16,163,127,0.1)', border:'1px solid rgba(16,163,127,0.3)', fontSize:12, fontWeight:600, color:'#10a37f' }}>
            {interest}
            <button onClick={() => removeInterest(interest)} style={{ background:'none', border:'none', color:'#10a37f', cursor:'pointer', padding:'0 2px', fontSize:14, lineHeight:1, opacity:0.7 }}>×</button>
          </div>
        ))}
      </div>
      <div style={{ position:'relative' }}>
        <input className="form-input"
          value={input}
          onChange={e => { setInput(e.target.value); setShowSuggestions(true); }}
          onFocus={() => setShowSuggestions(true)}
          onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
          onKeyDown={e => { if (e.key === 'Enter' && input.trim()) { e.preventDefault(); addInterest(input); } }}
          placeholder="Type an interest and press Enter..."
          style={{ fontSize:13 }}
        />
        {showSuggestions && filtered.length > 0 && (
          <div style={{ position:'absolute', top:'100%', left:0, right:0, zIndex:100, marginTop:4, background:'var(--bg-card)', border:'1px solid var(--border-subtle)', borderRadius:10, boxShadow:'0 4px 16px rgba(0,0,0,0.15)', maxHeight:200, overflowY:'auto' }}>
            {filtered.slice(0,8).map(s => (
              <div key={s} onMouseDown={e => { e.preventDefault(); addInterest(s); }} style={{ padding:'8px 14px', cursor:'pointer', fontSize:13, color:'var(--text-primary)', borderBottom:'1px solid var(--border-subtle)' }}
                onMouseEnter={e => e.currentTarget.style.background='var(--bg-elevated)'}
                onMouseLeave={e => e.currentTarget.style.background='transparent'}>
                {s}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ── Main CampaignDetailsStep ───────────────────────────────────────────────────
export default function CampaignDetailsStep({ data, onChange }) {
  const update = (field, value) => onChange({ ...data, [field]: value });

  const targeting = data.targeting || {};
  const updateTargeting = (field, value) => onChange({ ...data, targeting: { ...targeting, [field]: value } });

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:22 }}>

      {/* Campaign name */}
      <div>
        <label className="form-label">Campaign Name <span style={{ color:'#ef4444' }}>*</span></label>
        <input className="form-input" value={data.name || ''} onChange={e => update('name', e.target.value)}
          placeholder="e.g. Summer Sale 2025 — Meta + TikTok" />
      </div>

      {/* Date range */}
      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14 }}>
        <div>
          <label className="form-label">Start Date</label>
          <input className="form-input" type="date" value={data.startDate || ''} onChange={e => update('startDate', e.target.value)} />
        </div>
        <div>
          <label className="form-label">End Date (optional)</label>
          <input className="form-input" type="date" value={data.endDate || ''} onChange={e => update('endDate', e.target.value)} />
        </div>
      </div>

      {/* ── AUDIENCE TARGETING ─────────────────────────────────────── */}
      <div style={{ padding:'20px', borderRadius:12, border:'1px solid var(--border-subtle)', background:'var(--bg-elevated)' }}>
        <div style={{ fontSize:14, fontWeight:700, color:'var(--text-primary)', marginBottom:18 }}><Target size={14}/> Audience Targeting</div>

        {/* Age range */}
        <div style={{ marginBottom:18 }}>
          <label className="form-label">Age Range</label>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
            <div>
              <label style={{ fontSize:11, color:'var(--text-faint)', display:'block', marginBottom:4 }}>Minimum age</label>
              <select className="form-input" value={targeting.ageMin || 18} onChange={e => updateTargeting('ageMin', parseInt(e.target.value))}>
                {[13,18,21,25,30,35,40,45,50,55,60,65].map(a => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
            <div>
              <label style={{ fontSize:11, color:'var(--text-faint)', display:'block', marginBottom:4 }}>Maximum age</label>
              <select className="form-input" value={targeting.ageMax || 65} onChange={e => updateTargeting('ageMax', parseInt(e.target.value))}>
                {[18,21,25,30,35,40,45,50,55,60,65,100].map(a => <option key={a} value={a}>{a === 100 ? '65+' : a}</option>)}
              </select>
            </div>
          </div>
        </div>

        {/* Gender */}
        <div style={{ marginBottom:18 }}>
          <label className="form-label">Gender</label>
          <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
            {[
              { value:'all',    label:'All Genders' },
              { value:'male',   label:'Male' },
              { value:'female', label:'Female' },
            ].map(opt => {
              const selected = (targeting.gender || 'all') === opt.value;
              return (
                <button key={opt.value} type="button" onClick={() => updateTargeting('gender', opt.value)}
                  style={{ padding:'8px 18px', borderRadius:9, border:`1px solid ${selected ? 'var(--purple-primary)' : 'var(--border-subtle)'}`, background:selected?'rgba(124,58,237,0.12)':'var(--bg-card)', color:selected?'var(--purple-light)':'var(--text-muted)', fontWeight:selected?700:500, fontSize:13, cursor:'pointer', fontFamily:'DM Sans,sans-serif', transition:'all 0.15s' }}>
                  {opt.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* ── LOCATION — NEW PICKER ──────────────────────────────────── */}
        <div style={{ marginBottom:18 }}>
          <label className="form-label">
            Locations
            <span style={{ fontSize:11, color:'var(--text-faint)', fontWeight:400, marginLeft:8 }}>— search country or city</span>
          </label>
          <LocationPicker
            value={targeting.locations || []}
            onChange={locs => updateTargeting('locations', locs)}
          />
        </div>

        {/* Interests */}
        <div>
          <label className="form-label">
            Interests
            <span style={{ fontSize:11, color:'var(--text-faint)', fontWeight:400, marginLeft:8 }}>— optional</span>
          </label>
          <InterestPicker
            value={targeting.interests || []}
            onChange={interests => updateTargeting('interests', interests)}
          />
        </div>
      </div>

      {/* Campaign description */}
      <div>
        <label className="form-label">Description / Notes (optional)</label>
        <textarea className="form-input" rows={3} value={data.description || ''} onChange={e => update('description', e.target.value)}
          placeholder="Internal notes about this campaign..." style={{ resize:'vertical', lineHeight:1.6 }} />
      </div>

      {/* Tags */}
      <div>
        <label className="form-label">Tags (optional)</label>
        <input className="form-input" value={(data.tags || []).join(', ')} onChange={e => update('tags', e.target.value.split(',').map(t => t.trim()).filter(Boolean))}
          placeholder="e.g. summer, promo, retargeting" style={{ fontSize:13 }} />
        <div style={{ fontSize:11, color:'var(--text-faint)', marginTop:4 }}>Separate with commas</div>
      </div>

    </div>
  );
}
