import React, { useState } from 'react';
import Layout from '../components/shared/Layout';
import { analyticsAPI } from '../utils/api';
import { useLanguage } from '../context/LanguageContext';
import { AlertTriangle } from '../components/shared/Icons.js';

const KPI_KEYS = ['amountSpent','impressions','cpm','totalClicks','ctr','cpc','conversions','totalReach','addToCart'];

export default function ComparePage() {
  const { t } = useLanguage();
  const [start1,  setStart1]  = useState('');
  const [end1,    setEnd1]    = useState('');
  const [start2,  setStart2]  = useState('');
  const [end2,    setEnd2]    = useState('');
  const [result,  setResult]  = useState(null);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');

  const handleCompare = async () => {
    if (!start1||!end1||!start2||!end2) { setError('Please fill all date fields.'); return; }
    setLoading(true); setError(''); setResult(null);
    try {
      const r = await analyticsAPI.getCompare({ start1, end1, start2, end2 });
      setResult(r.data);
    } catch (err) { setError(err.response?.data?.message || err.message); }
    finally { setLoading(false); }
  };

  const fmt = (kpi, val) => {
    if (!val && val !== 0) return '—';
    if (kpi==='amountSpent'||kpi==='cpm'||kpi==='cpc') return `$${Number(val).toFixed(2)}`;
    if (kpi==='ctr') return `${Number(val).toFixed(2)}%`;
    return Number(val).toLocaleString();
  };

  const changeColor = (pct) => {
    if (!pct && pct !== 0) return 'var(--text-faint)';
    return pct > 0 ? '#16a34a' : pct < 0 ? '#ef4444' : 'var(--text-faint)';
  };

  return (
    <Layout>
      <div className="page-header">
        <div>
          <h1 className="page-title">{t('compare.title')}</h1>
          <p className="page-subtitle">{t('compare.subtitle')}</p>
        </div>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16, marginBottom:24, maxWidth:700 }}>
        {[
          { label:t('compare.period_1'), start:start1, end:end1, setStart:setStart1, setEnd:setEnd1 },
          { label:t('compare.period_2'), start:start2, end:end2, setStart:setStart2, setEnd:setEnd2 },
        ].map((p,i) => (
          <div key={i} className="glass-card" style={{ padding:20 }}>
            <div style={{ fontSize:14,fontWeight:700,color:'var(--text-primary)',marginBottom:14 }}>{p.label}</div>
            <div style={{ marginBottom:10 }}>
              <label className="form-label">{t('compare.start_date')}</label>
              <input className="form-input" type="date" value={p.start} onChange={e=>p.setStart(e.target.value)} />
            </div>
            <div>
              <label className="form-label">{t('compare.end_date')}</label>
              <input className="form-input" type="date" value={p.end} onChange={e=>p.setEnd(e.target.value)} />
            </div>
          </div>
        ))}
      </div>

      {error && <div style={{ padding:'10px 14px',borderRadius:8,marginBottom:16,background:'rgba(239,68,68,0.1)',border:'1px solid rgba(239,68,68,0.3)',color:'#ef4444',fontSize:13 }}><AlertTriangle size={14}/>️ {error}</div>}

      <button className="btn-primary" onClick={handleCompare} disabled={loading} style={{ marginBottom:28 }}>
        {loading ? t('common.loading') : t('compare.compare_btn')}
      </button>

      {result && (
        <div className="glass-card" style={{ padding:24, overflowX:'auto' }}>
          <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
            <thead>
              <tr>
                <th style={{ textAlign:'left',padding:'10px 14px',fontSize:12,fontWeight:700,color:'var(--text-muted)',textTransform:'uppercase',borderBottom:'1px solid var(--border-subtle)' }}>KPI</th>
                <th style={{ textAlign:'right',padding:'10px 14px',fontSize:12,fontWeight:700,color:'var(--text-muted)',textTransform:'uppercase',borderBottom:'1px solid var(--border-subtle)' }}>{t('compare.period_1')}</th>
                <th style={{ textAlign:'right',padding:'10px 14px',fontSize:12,fontWeight:700,color:'var(--text-muted)',textTransform:'uppercase',borderBottom:'1px solid var(--border-subtle)' }}>{t('compare.period_2')}</th>
                <th style={{ textAlign:'right',padding:'10px 14px',fontSize:12,fontWeight:700,color:'var(--text-muted)',textTransform:'uppercase',borderBottom:'1px solid var(--border-subtle)' }}>{t('compare.change')}</th>
              </tr>
            </thead>
            <tbody>
              {KPI_KEYS.map((kpi,i) => {
                const pct = result.changes?.[kpi];
                return (
                  <tr key={kpi} style={{ background:i%2===0?'var(--bg-elevated)':'transparent' }}>
                    <td style={{ padding:'10px 14px',fontWeight:600,color:'var(--text-primary)' }}>{t(`kpi.${kpi}`)}</td>
                    <td style={{ padding:'10px 14px',textAlign:'right',color:'var(--text-muted)' }}>{fmt(kpi, result.period1?.[kpi])}</td>
                    <td style={{ padding:'10px 14px',textAlign:'right',color:'var(--text-muted)' }}>{fmt(kpi, result.period2?.[kpi])}</td>
                    <td style={{ padding:'10px 14px',textAlign:'right',fontWeight:700,color:changeColor(pct) }}>
                      {pct != null ? `${pct > 0 ? '↑' : pct < 0 ? '↓' : ''} ${Math.abs(pct)}%` : '—'}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </Layout>
  );
}
