import React, { useState, useEffect } from 'react';
import Layout from '../components/shared/Layout';
import { useNavigate } from 'react-router-dom';
import { campaignAPI } from '../utils/api';
import { useLanguage } from '../context/LanguageContext';
import { PlatformIcons } from '../utils/platforms';
import { Campaigns } from '../components/shared/Icons.js';

export default function CampaignsPage() {
  const { t }       = useLanguage();
  const navigate    = useNavigate();
  const [campaigns, setCampaigns] = useState([]);
  const [loading,   setLoading]   = useState(true);
  const [filter,    setFilter]    = useState('all');
  const [search,    setSearch]    = useState('');
  const [deleting,  setDeleting]  = useState(null);

  useEffect(() => {
    campaignAPI.getAll({ limit:200 })
      .then(r => setCampaigns(r.data.campaigns || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const filtered = campaigns.filter(c => {
    const matchFilter = filter === 'all' || c.status === filter;
    const matchSearch = !search || c.name.toLowerCase().includes(search.toLowerCase());
    return matchFilter && matchSearch;
  });

  const handleDelete = async (id) => {
    if (!window.confirm(t('campaigns.confirm_delete'))) return;
    setDeleting(id);
    try { await campaignAPI.delete(id); setCampaigns(cs => cs.filter(c => c._id !== id)); }
    catch { alert('Delete failed'); }
    finally { setDeleting(null); }
  };

  const handleToggle = async (id) => {
    try {
      const res = await campaignAPI.toggleStatus(id);
      setCampaigns(cs => cs.map(c => c._id === id ? { ...c, status: res.data.status } : c));
    } catch { alert('Status update failed'); }
  };

  const statusColor = { active:'#16a34a', paused:'#d97706', draft:'#6b7280', completed:'#3b82f6' };

  const filterOptions = [
    { key:'all',    label:t('campaigns.filter_all')    },
    { key:'active', label:t('campaigns.filter_active') },
    { key:'paused', label:t('campaigns.filter_paused') },
    { key:'draft',  label:t('campaigns.filter_draft')  },
  ];

  return (
    <Layout>
      <div className="page-header">
        <div>
          <h1 className="page-title">{t('campaigns.title')}</h1>
          <p className="page-subtitle">{t('campaigns.subtitle')}</p>
        </div>
        <button className="btn-primary" onClick={() => navigate('/campaigns/new')}>
          {t('campaigns.new')}
        </button>
      </div>

      {/* Search + filter */}
      <div style={{ display:'flex', gap:12, marginBottom:22, flexWrap:'wrap', alignItems:'center' }}>
        <input className="form-input" placeholder={t('campaigns.search_placeholder')} value={search} onChange={e => setSearch(e.target.value)}
          style={{ flex:'1 1 220px', maxWidth:340, fontSize:13 }} />
        <div style={{ display:'flex', gap:6 }}>
          {filterOptions.map(f => (
            <button key={f.key} onClick={() => setFilter(f.key)} style={{ padding:'7px 14px', borderRadius:9, border:`1px solid ${filter===f.key?'var(--purple-primary)':'var(--border-subtle)'}`, background:filter===f.key?'rgba(124,58,237,0.12)':'transparent', color:filter===f.key?'var(--purple-light)':'var(--text-muted)', fontWeight:filter===f.key?700:500, fontSize:12, cursor:'pointer', fontFamily:'DM Sans,sans-serif', transition:'all 0.15s' }}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {loading ? (
        <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
          {[1,2,3].map(i => <div key={i} className="skeleton" style={{ height:88, borderRadius:14 }}/>)}
        </div>
      ) : filtered.length === 0 ? (
        <div className="glass-card" style={{ padding:48, textAlign:'center' }}>
          <div style={{ fontSize:48, marginBottom:14 }}><Campaigns size={40}/></div>
          <h3 style={{ fontSize:18, fontWeight:700, color:'var(--text-primary)', margin:'0 0 8px' }}>{t('campaigns.no_campaigns')}</h3>
          <p style={{ fontSize:13, color:'var(--text-muted)', margin:'0 0 20px' }}>{t('campaigns.no_campaigns_desc')}</p>
          <button className="btn-primary" onClick={() => navigate('/campaigns/new')}>{t('campaigns.new')}</button>
        </div>
      ) : (
        <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
          {filtered.map(campaign => (
            <div key={campaign._id} className="glass-card" style={{ padding:'16px 20px', display:'flex', alignItems:'center', gap:14, flexWrap:'wrap', cursor:'pointer' }}
              onClick={() => navigate(`/campaigns/${campaign._id}`)}>
              {/* Status dot */}
              <div style={{ width:10, height:10, borderRadius:'50%', background:statusColor[campaign.status]||'#6b7280', flexShrink:0 }}/>
              {/* Name + meta */}
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:14, fontWeight:700, color:'var(--text-primary)', marginBottom:3, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{campaign.name}</div>
                <div style={{ fontSize:12, color:'var(--text-faint)', display:'flex', gap:8, flexWrap:'wrap' }}>
                  <span>{t('campaigns.objective')}: {campaign.objective}</span>
                  <span>·</span>
                  <span>{t('campaigns.budget')}: ${campaign.totalBudget?.toLocaleString()}</span>
                  {campaign.tags?.includes('imported') && <span style={{ padding:'1px 7px', borderRadius:10, background:'rgba(59,130,246,0.1)', border:'1px solid rgba(59,130,246,0.25)', color:'#3b82f6', fontWeight:600 }}>{t('campaigns.imported')}</span>}
                </div>
              </div>
              {/* Platform icons */}
              <div style={{ display:'flex', gap:6, flexShrink:0 }}>
                {campaign.platforms?.map(p => { const Icon = PlatformIcons[p.platform]; return Icon ? <Icon key={p.platform} size={18}/> : null; })}
              </div>
              {/* Status badge */}
              <div style={{ padding:'4px 12px', borderRadius:20, fontSize:11, fontWeight:700, background:`${statusColor[campaign.status]}18`, color:statusColor[campaign.status]||'#6b7280', border:`1px solid ${statusColor[campaign.status]}30`, flexShrink:0 }}>
                {t(`common.${campaign.status}`) || campaign.status}
              </div>
              {/* Actions */}
              <div style={{ display:'flex', gap:6, flexShrink:0 }} onClick={e => e.stopPropagation()}>
                <button className="btn-secondary" onClick={() => handleToggle(campaign._id)} style={{ fontSize:11, padding:'5px 10px' }}>
                  {campaign.status === 'active' ? `⏸ ${t('campaigns.pause_campaign')}` : `▶ ${t('campaigns.resume_campaign')}`}
                </button>
                <button onClick={() => handleDelete(campaign._id)} disabled={deleting===campaign._id}
                  style={{ padding:'5px 10px', borderRadius:8, border:'1px solid rgba(239,68,68,0.3)', background:'rgba(239,68,68,0.08)', color:'#ef4444', cursor:'pointer', fontSize:11, fontWeight:600 }}>
                  {deleting===campaign._id ? '...' : t('common.delete')}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </Layout>
  );
}
