export const formatKPI = (value, format) => {
  if (value === undefined || value === null) return '—';
  switch (format) {
    case 'currency': return `$${value >= 1000 ? (value / 1000).toFixed(1) + 'K' : value.toFixed(2)}`;
    case 'percent': return `${value.toFixed(2)}%`;
    case 'number': return value >= 1000000 ? `${(value / 1000000).toFixed(1)}M` : value >= 1000 ? `${(value / 1000).toFixed(1)}K` : value.toString();
    case 'roi':  return `${Number(value) >= 0 ? '+' : ''}${Number(value).toFixed(1)}%`;
    case 'roas': return `${Number(value).toFixed(2)}x`;
    default: return value.toString();
  }
};